// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    // allow C to transfer its whole balance to the owner (this contract)
    receive() external payable {}

    function testFuzz_property(uint96 amount) public {
        // keep the domain wide but admissible: a positive fundable amount
        vm.assume(amount > 0);

        // fund C with the fuzzed amount
        vm.deal(address(c), uint256(amount));
        uint256 before = address(this).balance;

        // owner (deployer = this contract) withdraws everything
        c.withdrawAll();

        // the reference drains C completely, delivering the funds to the owner;
        // the mutant leaves the funds in C
        assertTrue(address(c).balance == 0 && address(this).balance == before + uint256(amount));
    }
}
